insert into document_template_sections (document_template_id, code, title, sort_order, content_type, html_template, source_content_block_type, content_block_scope) values

-- ---------- LIVRET D'ACCUEIL ----------
('livret_accueil', 'bienvenue', 'Bienvenue', 1, 'rich_text', '<p>Bienvenue chez <strong>{{company_name}}</strong>. Ce livret d''accueil a pour objectif de vous donner toutes les informations pratiques utiles au bon déroulement de votre formation <strong>« {{training_name}} »</strong>.</p>', null, 'global'),
('livret_accueil', 'presentation_organisme', 'Présentation de l''organisme', 2, 'rich_text', '<p>{{company_name}} ({{commercial_name}}) est un organisme de formation certifié Qualiopi, dirigé par {{director_name}}. {{sole_practitioner_note}}</p><ul><li>Adresse : {{address}}</li><li>Téléphone : {{phone}} — Email : {{email}}</li><li>Site internet : {{company_website}}</li></ul>', null, 'global'),
('livret_accueil', 'interlocuteurs', 'Vos interlocuteurs', 3, 'rich_text', '<ul><li>Référent pédagogique : {{pedagogical_referent_name}} — {{pedagogical_referent_email}} / {{pedagogical_referent_phone}}</li><li>Référent administratif : {{administrative_referent_name}} — {{administrative_referent_email}} / {{administrative_referent_phone}}</li><li>Formateur·rice de votre session : {{trainer_name}}</li></ul>', null, 'global'),
('livret_accueil', 'votre_formation', 'Votre formation', 4, 'rich_text', '<table><tbody><tr><th>Intitulé</th><td>{{training_name}}</td></tr><tr><th>Dates</th><td>Du {{training_start_date}} au {{training_end_date}}</td></tr><tr><th>Durée</th><td>{{training_duration}} heures</td></tr><tr><th>Modalité</th><td>{{training_modality}}</td></tr><tr><th>Lieu</th><td>{{training_location}}</td></tr></tbody></table><p>Le programme détaillé (objectifs, contenu, méthodes, modalités d''évaluation) vous a été remis séparément.</p>', null, 'global'),
('livret_accueil', 'organisation_pratique', 'Organisation pratique', 5, 'rich_text', '<p>Les horaires précis vous sont communiqués dans votre convocation. En cas d''empêchement, prévenez {{administrative_referent_name}} au plus tôt. Votre présence est attestée par la signature d''une feuille d''émargement à chaque demi-journée. Pour une formation à distance, un accès à {{technical_provider_name}} vous est communiqué avant le début de l''action.</p>', null, 'global'),
('livret_accueil', 'accessibilite', 'Accessibilité et situation de handicap', 6, 'rich_text', '<p>Si vous êtes en situation de handicap et avez besoin d''un aménagement (matériel, rythme, durée, accessibilité des locaux...), contactez notre référent handicap, {{disability_referent_name}} ({{disability_referent_email}} / {{disability_referent_phone}}), le plus tôt possible avant le début de la formation afin d''étudier ensemble les solutions adaptées.</p>', null, 'global'),
('livret_accueil', 'reclamations', 'Réclamations', 7, 'rich_text', '<p>Si vous rencontrez une difficulté pendant votre formation, vous pouvez la signaler à tout moment à {{pedagogical_referent_name}}. Pour toute réclamation formelle, écrivez à {{complaints_email}} — elle sera traitée selon notre procédure de traitement des réclamations, disponible sur demande.</p>', null, 'global'),
('livret_accueil', 'reglement', 'Règlement intérieur', 8, 'rich_text', '<p>Le règlement intérieur applicable pendant votre formation vous est remis en document séparé et vous a été communiqué avant votre inscription définitive.</p>', null, 'global'),

